/**
 * Builds the API Reference sidebar data from pages/api-reference into
 * public/api-reference-nav/ (gitignored — regenerated by `dev` and `build`):
 *
 *   networks.json   [{ slug, title }]                 — network selector
 *   <slug>.json     [{ name, title, methods }]        — one network's sections
 *
 * A method is stored as its file name, or as [name, title] when its sidebar
 * title differs. Routes are not stored: lib/apiReferenceNav.ts derives them
 * as /api-reference/<slug>/<section>/<method>.
 */
const fs = require("fs");
const path = require("path");

const API_REF_DIR = path.join(__dirname, "..", "pages", "api-reference");
const OUT_DIR = path.join(__dirname, "..", "public", "api-reference-nav");

function readMeta(dir) {
  const metaPath = path.join(dir, "_meta.json");
  if (!fs.existsSync(metaPath)) return {};
  return JSON.parse(fs.readFileSync(metaPath, "utf-8"));
}

function titleFor(meta, key, fallback) {
  const entry = meta[key];
  if (typeof entry === "string") return entry;
  if (entry && typeof entry === "object" && entry.title) return entry.title;
  return fallback;
}

/** Drops a trailing " API" from a network's display title (e.g. "Ethereum API" -> "Ethereum").
 * Used only for the network dropdown/selector — leaves _meta.json itself untouched, so
 * Nextra's own page titles/breadcrumbs still show the full "X API" form. */
function stripApiSuffix(title) {
  return title.replace(/\s+API$/i, "");
}

function isPageFile(name) {
  return name.endsWith(".mdx") || name.endsWith(".md") || name.endsWith(".tsx");
}

function buildMethods(sectionDir) {
  const meta = readMeta(sectionDir);
  const names = new Set(
    fs
      .readdirSync(sectionDir, { withFileTypes: true })
      .filter((e) => e.isFile() && isPageFile(e.name))
      .map((e) => e.name.replace(/\.(mdx?|tsx)$/, ""))
      .filter((name) => name !== "index")
  );

  // A method's old .mdx and migrated .tsx can briefly coexist under the same
  // base name — the Set keeps it listed once.
  return [...names].map((name) => {
    const title = titleFor(meta, name, name);
    return title === name ? name : [name, title];
  });
}

function buildSections(networkDir) {
  const meta = readMeta(networkDir);
  return fs
    .readdirSync(networkDir, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => ({
      name: e.name,
      title: titleFor(meta, e.name, e.name),
      methods: buildMethods(path.join(networkDir, e.name)),
    }));
}

function main() {
  const rootMeta = readMeta(API_REF_DIR);
  const networkDirs = fs
    .readdirSync(API_REF_DIR, { withFileTypes: true })
    .filter((e) => e.isDirectory());

  fs.rmSync(OUT_DIR, { recursive: true, force: true });
  fs.mkdirSync(OUT_DIR, { recursive: true });

  const networks = networkDirs.map((e) => ({
    slug: e.name,
    title: stripApiSuffix(titleFor(rootMeta, e.name, e.name)),
  }));
  fs.writeFileSync(path.join(OUT_DIR, "networks.json"), JSON.stringify(networks));

  for (const e of networkDirs) {
    const sections = buildSections(path.join(API_REF_DIR, e.name));
    fs.writeFileSync(path.join(OUT_DIR, `${e.name}.json`), JSON.stringify(sections));
  }

  console.log(`✔ Wrote ${networks.length} network(s) -> ${path.relative(process.cwd(), OUT_DIR)}/`);
}

main();
